{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investments — Aromatic Programs | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6efe6;--card:#fff5ea;--accent:#8a4b2f;--muted:#7a5a46;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; background:linear-gradient(180deg,var(--bg),#fbf6ee);color:#3b2f26}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(90deg,rgba(138,75,47,0.06),transparent);border-bottom:1px solid rgba(58,44,35,0.04)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#b26a4b);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:980px;margin:36px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start}
    .hero .lead{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(58,44,35,0.06)}
    .hero h1{margin:0 0 8px 0;font-size:24px;color:var(--accent)}
    .hero p{margin:0;color:#5b473b}
    aside.card{background:var(--glass);padding:18px;border-radius:10px}
    .tiers{display:flex;gap:14px;margin-top:20px}
    .tier{flex:1;background:#fff;padding:18px;border-radius:10px;border:1px solid rgba(58,44,35,0.04)}
    .tier h3{margin:0;color:var(--accent)}
    .price{font-size:20px;margin-top:8px;font-weight:700}
    .meta{color:#7b6458;font-size:13px;margin-top:10px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    .note{font-size:13px;color:#6b5649;margin-top:12px}
    .widget{margin-top:22px;padding:14px;background:linear-gradient(180deg,#fff7f1, #fff2ea);border-radius:10px}
    label{display:block;font-size:13px;color:#5d4738;margin-top:10px}
    select,input[type="number"],textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(58,44,35,0.08);margin-top:6px}
    button.small{margin-top:10px;padding:8px 12px;border-radius:8px;border:0;background:#85614f;color:#fff;font-weight:700}
    footer{max-width:980px;margin:36px auto;padding:18px 28px;color:#6e5850;border-top:1px solid rgba(58,44,35,0.04)}
    .blend-result{background:#fff;padding:12px;border-radius:8px;margin-top:10px;border:1px dashed rgba(138,75,47,0.12)}
    .copy{background:#fff;padding:8px;border-radius:8px;border:1px solid rgba(58,44,35,0.06);display:inline-block;margin-top:8px}
    /* Pattern background */
    .pattern{position:fixed;right:0;top:0;opacity:0.08;width:360px;height:100vh;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-size:contain}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.pattern{display:none}.brand{gap:8px}nav a{display:none}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div class="brand"><div class="logo">A</div><div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
    </div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Elixirs</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div class="lead">
        <h1>Programs & Pricing — choose your aromatic arc</h1>
        <p>We design focused aromatic work that may support emotional tone, sleep, or focus. Each offering is a guided experience — an investment in a gentle, practical routine you can carry home.</p>

        <div class="tiers">
          <div class="tier">
            <h3>Single Session — Aromatic Consultation</h3>
            <div class="price">$120</div>
            <div class="meta">60 minutes. Personalized blending and at-home outline.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Book this session</a>
          </div>
          <div class="tier">
            <h3>Essence Path — 3-Session Series</h3>
            <div class="price">$330</div>
            <div class="meta">Three 50–60 minute sessions. Integration guide + mini blend.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Begin the path</a>
          </div>
          <div class="tier">
            <h3>Intensive Deep-Craft</h3>
            <div class="price">$580</div>
            <div class="meta">Four sessions + custom at-home kit and ongoing notes.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Request a spot</a>
          </div>
        </div>

        <div class="note">Prices are presented as guidance and may be adjusted to meet your needs. All work is non-medical and intended as supportive practice.</div>
      </div>

      <aside class="card">
        <h4 style="margin:0;color:var(--accent)">Quick mix: Blend builder</h4>
        <p style="margin:6px 0 0 0;color:#6b5347;font-size:14px">Choose a vibe and volume to see a safe dilution guide and a printable blend card.</p>

        <div class="widget" id="blendWidget">
          <label for="vibeSelect">Desired vibe</label>
          <select id="vibeSelect">
            <option value="calm">Calm & grounding</option>
            <option value="clarity">Clarity & focus</option>
            <option value="sleep">Evening ease</option>
            <option value="uplift">Uplift & brightening</option>
          </select>
          <label for="methodSelect">Primary application</label>
          <select id="methodSelect">
            <option value="topical">Topical (diluted)</option>
            <option value="inhalation">Inhalation</option>
          </select>
          <label for="volumeSelect">Total bottle volume (ml)</label>
          <select id="volumeSelect">
            <option value="10">10 ml</option>
            <option value="15">15 ml</option>
            <option value="30">30 ml</option>
          </select>
          <button class="small" id="buildBlend">Create blend card</button>

          <div id="blendOutput" class="blend-result" aria-live="polite" style="display:none"></div>
          <button id="copyBlend" class="copy" style="display:none">Copy blend text</button>
        </div>

        <div style="font-size:12px;color:#6b5649;margin-top:10px">All blends are non-medical. Follow dilution, patch test, and pet/pregnancy notes in the FAQ.</div>
      </aside>
    </section>

    <section style="margin-top:28px">
      <h3 style="color:var(--accent)">Why this structure?</h3>
      <p style="color:#5b463b">Our pricing frames work as short arcs — single explorations, a focused path, or an intensive for deeper craft. Each is grounded in clear at-home practices so your learning stays practical and gentle.</p>
    </section>

    <section style="margin-top:20px">
      <h4 style="color:var(--accent)">Still deciding?</h4>
      <p style="color:#6b5649">Book a 20-minute clarity call (complimentary) to map the right offering for you. Use the reserve link to request a slot.</p>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">Request clarity call</a>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="color:#7b6458;font-size:13px">© <span id="year"></span></div>
    </div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    function dropsPerMl(){return 20;} // approximate

    const vibes = {
      calm:{name:'Calm & grounding', oils:[{o:'Lavender',pct:40},{o:'Cedarwood',pct:35},{o:'Bergamot',pct:25}]},
      clarity:{name:'Clarity & focus', oils:[{o:'Sweet Orange',pct:40},{o:'Rosemary',pct:30},{o:'Peppermint',pct:30}]},
      sleep:{name:'Evening ease', oils:[{o:'Lavender',pct:50},{o:'Roman Chamomile',pct:25},{o:'Vetiver',pct:25}]},
      uplift:{name:'Uplift & brightening', oils:[{o:'Grapefruit',pct:45},{o:'Lavender',pct:25},{o:'Ginger',pct:30}]}
    };

    document.getElementById('buildBlend').addEventListener('click',()=>{
      const vibeKey=document.getElementById('vibeSelect').value;
      const method=document.getElementById('methodSelect').value;
      const volume=Number(document.getElementById('volumeSelect').value);
      const info=vibes[vibeKey];
      const output=document.getElementById('blendOutput');
      const copyBtn=document.getElementById('copyBlend');

      // dilution guidance
      let dilutionPct= method === 'topical' ? 2 : 1; // adult guidance
      let note = method === 'topical' ? 'Suggested topical dilution for most adults: ' + dilutionPct + '% (follow patch test).' : 'Suggested inhalation dilution: diffuse 3-6 drops per 100ml or add to personal inhaler.';

      // compute drops per oil
      const totalDrops=Math.round(volume * dropsPerMl());
      const totalEssentialDrops = Math.max(1, Math.round(totalDrops * (dilutionPct/100)));
      // allocate by oil percent
      let lines = [];
      info.oils.forEach(item=>{
        const d = Math.max(1, Math.round(totalEssentialDrops * (item.pct/100)));
        lines.push(item.o + ': ' + d + ' drops');
      });

      const blendCard = 'Blend: ' + info.name + '\nVolume: ' + volume + ' ml\nApplication: ' + (method === 'topical' ? 'Topical (diluted)' : 'Inhalation') + '\nDilution guidance: ' + dilutionPct + '% (adult guidance)\n\nOils and drops:\n' + lines.join('\n') + '\n\nNotes: ' + note + '\nSafety: Do patch test; avoid contact with eyes. See FAQ for notes on pets and pregnancy. This is not medical advice.';

      output.style.display='block';
      output.textContent = '';
      const pre = document.createElement('pre'); pre.style.margin=0; pre.style.whiteSpace='pre-wrap'; pre.textContent=blendCard;
      output.appendChild(pre);
      copyBtn.style.display='inline-block';
      copyBtn.onclick = ()=>{navigator.clipboard.writeText(blendCard).then(()=>{copyBtn.textContent='Copied'}).catch(()=>{copyBtn.textContent='Copy failed'})};
    });
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Origin & Approach | {{BUSINESS_NAME}}</title>
  <style>
    :root{--sand:#f2e9de;--rich:#7a4b36;--muted:#6b5347}
    body{margin:0;font-family:Inter,system-ui,-apple-system,'Segoe UI',Roboto; background:linear-gradient(180deg,var(--sand),#fff);color:#3d2b22}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-bottom:1px solid rgba(61,43,34,0.04)}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,#7a4b36,#b36a4a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:960px;margin:28px auto;padding:20px}
    .intro{display:flex;gap:22px;align-items:flex-start}
    .intro .story{flex:2;background:#fff;padding:18px;border-radius:12px}
    .intro aside{flex:1;padding:14px;background:rgba(122,75,54,0.06);border-radius:10px}
    h1{color:var(--rich);margin:0}
    p{color:#5e473a}
    .values{display:flex;gap:12px;margin-top:14px}
    .pill{background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(61,43,34,0.04)}
    footer{max-width:960px;margin:28px auto;padding:18px 22px;color:#6f5750;border-top:1px solid rgba(61,43,34,0.04)}
    .widget{margin-top:14px;padding:12px;background:linear-gradient(180deg,#fff,#fff6f3);border-radius:10px}
    label{display:block;font-size:13px;color:#5d4738;margin-top:8px}
    select,input{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid rgba(61,43,34,0.06)}
    button{margin-top:10px;padding:10px 12px;border-radius:8px;border:0;background:var(--rich);color:#fff;font-weight:700}
    .blend-card{background:#fff;padding:10px;border-radius:8px;margin-top:12px;border-left:4px solid #d9a58e}
    .muted-note{font-size:13px;color:#7b6357;margin-top:10px}
    .pattern{position:fixed;left:0;bottom:0;opacity:0.08;width:320px;height:320px;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-size:contain}
    @media(max-width:820px){.intro{flex-direction:column}.pattern{display:none}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><div class="logo">A</div><div><strong>{{BUSINESS_NAME}}</strong><div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div></div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Elixirs</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="intro">
      <div class="story">
        <h1>Origin story & guiding practice</h1>
        <p>I work with scent as a craft: melodic, tactile, and quietly effective. My training blends botanical tradition with modern safety practices so the rituals you take home are practical and kind. Aromas may support mood and routine — never replace care from clinicians.</p>

        <div class="values">
          <div class="pill"><strong>Safety-forward</strong><div style="color:#6b5347">Patch tests, dilution, and pet-safe choices are standard.</div></div>
          <div class="pill"><strong>Personalized</strong><div style="color:#6b5347">Blends and at-home plans shaped to your environment and rhythms.</div></div>
          <div class="pill"><strong>Practical</strong><div style="color:#6b5347">Simple steps you can fold into daily life.</div></div>
        </div>

        <h3 style="margin-top:18px;color:var(--rich)">Who I work with</h3>
        <p style="color:#5b463b">People seeking sensory tools that may support sleep, focus, emotional balance, or ritual. All offerings avoid medical claims; language focuses on what scent may support.</p>

        <h3 style="margin-top:18px;color:var(--rich)">Work that lands at home</h3>
        <p style="color:#5b463b">When a session ends, you receive clear instructions, a small blend or kit option, and steps for integrating the practice into your day.</p>

      </div>

      <aside>
        <div style="font-weight:700;color:var(--rich)">Meet the tools</div>
        <p style="color:#6b5347">A curated selection of essential oils, carrier bases, and inhalers. All ingredients are chosen for quality and safety.</p>

        <div class="widget">
          <h4 style="margin:0;color:var(--rich)">Micro blend builder</h4>
          <p style="margin:6px 0 0 0;color:#6b5347;font-size:13px">Pick a mood and application to preview a safe dilution and blend card.</p>
          <label for="vibe2">Mood</label>
          <select id="vibe2">
            <option value="clarity">Clarity</option>
            <option value="calm">Calm</option>
            <option value="sleep">Evening ease</option>
            <option value="uplift">Uplift</option>
          </select>
          <label for="app2">Application</label>
          <select id="app2">
            <option value="topical">Topical (diluted)</option>
            <option value="inhalation">Inhalation</option>
          </select>
          <button id="build2">Preview</button>
          <div id="card2" class="blend-card" style="display:none"></div>
          <button id="copy2" style="display:none;margin-top:8px;" class="copy">Copy text</button>
        </div>

        <div class="muted-note">I keep small-group workshops during the year and occasional intensives. For inquiries, use the reserve link.</div>
      </aside>
    </section>

    <section style="margin-top:22px">
      <h3 style="color:var(--rich)">FAQ — safety highlights</h3>
      <p style="color:#5b463b"><strong>Patch test:</strong> Apply a small diluted amount to the inner arm, wait 24 hours for irritation. <strong>Pets:</strong> Some oils may be harmful to pets; avoid diffuse near small animals and consult veterinarian. <strong>Pregnancy & nursing:</strong> Many oils are contraindicated; please disclose pregnancy status before using topical or internal strategies. This practice is supportive, not medical.</p>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>{{BUSINESS_NAME}} · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="color:#7b6458;font-size:13px">{{CITY}}, {{STATE}}</div>
    </div>
  </footer>

  <script>
    // Duplicate of blend logic but compact
    function smallDrops(){return 20}
    const map = {
      clarity:{name:'Clarity', oils:[{o:'Rosemary',pct:40},{o:'Sweet Orange',pct:30},{o:'Peppermint',pct:30}]},
      calm:{name:'Calm', oils:[{o:'Lavender',pct:50},{o:'Cedarwood',pct:30},{o:'Bergamot',pct:20}]},
      sleep:{name:'Evening ease', oils:[{o:'Roman Chamomile',pct:40},{o:'Lavender',pct:40},{o:'Vetiver',pct:20}]},
      uplift:{name:'Uplift', oils:[{o:'Grapefruit',pct:50},{o:'Ginger',pct:20},{o:'Lavender',pct:30}]}
    };

    document.getElementById('build2').addEventListener('click',()=>{
      const v=document.getElementById('vibe2').value;
      const a=document.getElementById('app2').value;
      const info=map[v];
      const vol=10; // micro-preview
      const dilution = a==='topical'?1.5:1; // preview guidance
      const totalDrops = Math.round(vol * smallDrops());
      const essentialDrops = Math.max(1, Math.round(totalDrops * (dilution/100)));
      let lines=[];
      info.oils.forEach(it=>{const d=Math.max(1,Math.round(essentialDrops*(it.pct/100)));lines.push(it.o+': '+d+' drops')});
      const txt = info.name + ' — ' + (a==='topical'?'Topical guidance: '+dilution+'%':'Inhalation suggestion') + '\n' + lines.join('\n') + '\nSafety: patch test; avoid eyes; see FAQ.';
      const box=document.getElementById('card2'); box.style.display='block'; box.textContent=txt;
      const cbtn=document.getElementById('copy2'); cbtn.style.display='inline-block'; cbtn.onclick=()=>navigator.clipboard.writeText(txt).then(()=>cbtn.textContent='Copied')
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve a Session | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff7f1;--accent:#8a4b2f;--muted:#6b5347}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto; background:linear-gradient(180deg,var(--bg),#fff);color:#3d2b27}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid rgba(61,43,34,0.04)}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:940px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:20px}
    .panel{background:#fff;padding:18px;border-radius:12px;border:1px solid rgba(61,43,34,0.04)}
    h1{color:var(--accent);margin:0}
    label{display:block;margin-top:10px;color:#5d4738}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(61,43,34,0.06);margin-top:6px}
    button.primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;font-weight:800;margin-top:12px}
    .planner{margin-top:12px;padding:12px;background:linear-gradient(180deg,#fff,#fff6f3);border-radius:10px}
    .summary{background:#fff;padding:10px;border-radius:8px;margin-top:10px;border-left:4px solid #d9a58e}
    .copy{margin-top:8px;padding:8px;border-radius:8px;background:#fff;border:1px solid rgba(61,43,34,0.06)}
    .pattern{position:fixed;right:0;bottom:0;opacity:0.06;width:360px;height:360px;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-size:contain}
    @media(max-width:880px){.grid{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><div style="width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,#8a4b2f,#b26a4b);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800">A</div><div><strong>{{BUSINESS_NAME}}</strong><div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div></div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Elixirs</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <div class="panel">
          <h1>Reserve a session</h1>
          <p style="color:#6b5347">Use this form to request a spot. After submission you will receive next steps to confirm time and prepare.</p>

          <form id="bookingForm">
            <label for="name">Full name</label>
            <input id="name" required>
            <label for="email">Email</label>
            <input id="email" type="email" required>
            <label for="phone">Phone</label>
            <input id="phone" type="tel">
            <label for="service">Preferred offering</label>
            <select id="service">
              <option value="single">Single Aromatic Consultation</option>
              <option value="path">Essence Path — 3 sessions</option>
              <option value="intensive">Intensive Deep-Craft</option>
            </select>
            <label for="when">Preferred days / times</label>
            <input id="when" placeholder="e.g., weekday mornings or evenings">

            <div style="margin-top:10px">Ready to book?</div>
            <button class="primary" type="submit">Request this slot</button>
          </form>

          <div style="font-size:13px;color:#6b5347;margin-top:12px">A quick reply will include questionnaire and guidance for a safe, tailored session. Payment details are shared after confirmation.</div>
        </div>

        <div class="panel" style="margin-top:18px">
          <h3 style="margin:0;color:var(--accent)">Session Planner</h3>
          <p style="color:#6b5347;margin-top:8px">Build a short plan to make the session actionable. Export a plaintext summary to paste into notes or emails.</p>

          <div class="planner">
            <label for="goal">Primary goal</label>
            <select id="goal">
              <option value="sleep">Support sleep routine</option>
              <option value="focus">Support focus</option>
              <option value="calm">Reduce daily tension</option>
