      const cbtn = document.getElementById('copyPlan'); cbtn.style.display='inline-block'; cbtn.onclick=()=>{
        navigator.clipboard.writeText(text).then(()=>{cbtn.textContent='Copied'}).catch(()=>{cbtn.textContent='Copy failed'})
